// Agents in grouped or priority views; parents take their most urgent sub-agent's place.

import { View, div, image, svg } from "gpui-kit";
import { v_flex, h_flex, ScrollHandle } from "gpui-base";
import { agents, terminals, panes, focused, spaces, run, theme, shared, setShared, setAgentOrder, openOverlay, closeOverlay, props, window, layout, nextCommand, exec, watchFolder, notify, checking } from "herdr";
// <flat-tokens> generated by lib/herdr_flat/sync from lib/herdr_flat/flat.js; edit there
const R = 1;
const LINE = 1;
const UNIT = 5;
const S1 = UNIT;
const S2 = UNIT * 2;
const S3 = UNIT * 3;
const S4 = UNIT * 4;
const HAIR = 2;
const TEXT = 13;
const SMALL = 11;
const H3 = 15;
const H2 = 18;
const H1 = 22;
// </flat-tokens>

function find(node, id) {
  if (node?.id === id) return node;
  for (const child of node?.children ?? []) {
    const found = find(child, id);
    if (found) return found;
  }
  return null;
}

// The sidebar's rail goes by its width, not a flag: dragging its edge narrows it too.
const narrow = () => (find(layout(), "sidebar")?.size?.px ?? Infinity) < 160;

// To the rail (on macOS wide enough for the traffic lights), or back to the width it had.
function toggleSidebar() {
  const width = find(layout(), "sidebar")?.size?.px;
  if (!narrow()) setShared("sidebar.width", width);
  // Mods edited before the rail went by width still read the flag.
  setShared("sidebar.collapsed", !narrow());
  run("layout.resize", { id: "sidebar", px: narrow() ? (shared("sidebar.width") ?? 268) : window()?.platform === "macos" ? 76 : 44 });
}

// Drops what an agent puts before its title: a status glyph or spinner and the separator
// after it ("✦  Working", "⠋ - Thinking"), Codex's blinking "[ ! ] " / "[ . ] " mark, and
// OpenCode's "OC | " prefix. Stops at an opening bracket or quote, so a title that starts
// with one ("[web] login") keeps it, and at an emoji ("🔴 login", "❤️ deploy"), except for
// known status marks.
const clean = (s) => (s ?? "").replace(/^(?:\[ [!.] \] |[✋⏳]\uFE0F?(?=\s)|(?!(?:\p{Emoji}\uFE0F|[#*]\u20E3))[^\p{L}\p{N}\p{Ps}\p{Pi}\p{Emoji_Presentation}])+/u, "").replace(/^OC \| /, "").trim();

function leadPanes(all) {
  const leads = new Map();
  for (const p of all) {
    if (!p.terminal) continue;
    const current = leads.get(p.tab);
    // First agent, else first focused terminal, else first terminal in the tab.
    if (!current || (!current.program?.agent && (p.program?.agent || (!current.focused && p.focused)))) leads.set(p.tab, p);
  }
  return leads;
}

// The session title an agent labelled its terminal with (dotfiles' herdr/title-report.mjs),
// else none. `l` is a pane (terminal) or an agent (address).
function sessionTitle(byAddress, l) {
  return byAddress.get(l?.terminal ?? l?.address)?.labels?.[`session_title.${l?.program?.key}`] || null;
}

function title(tab, l, own) {
  const prog = l?.program?.name;
  const raw = own || l?.title || "";
  const live = clean(raw);
  // clean() would strip a path's leading ~ or /: test the title with only its status glyph gone.
  const path = /^[~/]|^[A-Za-z]:\\/.test(raw.replace(/^[^\p{L}\p{N}~/]+/u, ""));
  const telling = live && live !== (l?.terminal ?? l?.address) && live !== prog && !path && !live.includes("@") && live.toLowerCase() !== l?.program?.key;
  return (tab.name === prog || !tab.named) && telling ? live : tab.name;
}
const RANK = { blocked: 4, done: 3, working: 2, idle: 1 };
// A sub-agent without a pane isn't in agents(): its raw word, error counting as
// blocked. It's never done: it reports to its parent, and the parent's done is the news.
// A kept sub-agent (one with a pane) is in agents() too: it keeps its own status, done included.
const kidStatus = (k, listed) => {
  if (listed.has(k.address)) return listed.get(k.address);
  const s = k.status;
  return s === "error" ? "blocked" : s === "done" ? "idle" : s;
};
const SORTS = [
  { id: "priority", label: "Priority", icon: "clock" },
  { id: "grouped", label: "Grouped by space", icon: "layers" },
];
const sortOf = () => SORTS.find((s) => s.id === shared("agents.sort")) ?? SORTS[0];
const SECTION = { 4: "Needs you", 3: "Done", 2: "Working", 1: "Idle" };
const SECTION_STATUS = { 4: "blocked", 3: "done", 2: "working" };

function duration(ms) {
  const m = Math.floor(ms / 60000);
  if (m < 1) return "<1m";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  return h < 24 ? `${h}h` : `${Math.floor(h / 24)}d`;
}

// The agent's icon from the app's program table: a one-color glyph or a picture.
function icon(p, size, color) {
  if (!p?.icon) return null;
  return p.tint ? svg(p.icon).size(size).flex_none().text_color(color) : image(p.icon).w(size).h(size).flex_none();
}

const GIT_FALLBACK_MS = 60000;
const PR_POLL_MS = 60000;
const PR_PENDING_POLL_MS = 20000;
const PR_TURN_COOLDOWN_MS = 10000;
const GIT_AT_ONCE = 4;
const PR_AT_ONCE = 4;
const PR_FIELDS = "number,url,state,isDraft,reviewDecision,mergeable,mergeStateStatus,statusCheckRollup";
const FAIL_CONCLUSIONS = new Set(["FAILURE", "TIMED_OUT", "ACTION_REQUIRED", "STARTUP_FAILURE"]);

const machineOf = (addr) => (addr && addr.includes("/") ? addr.split("/")[0] : null);
const placeKeyOf = (addr, cwd) => (cwd ? JSON.stringify([machineOf(addr), cwd]) : null);

function isDefaultBranch(g) {
  if (!g || !g.branch || g.branch === "(detached)") return true;
  if (g.defaultBranch) return g.branch === g.defaultBranch;
  return g.branch === "main" || g.branch === "master";
}

function parseStatusV2(stdout) {
  let oid = null;
  let branch = "(detached)";
  let hasUpstream = false;
  let ahead = 0;
  let behind = 0;
  let dirty = 0;
  for (const line of stdout.split("\n")) {
    if (!line) continue;
    if (line.startsWith("# ")) {
      if (line.startsWith("# branch.oid ")) oid = line.slice(13).trim();
      else if (line.startsWith("# branch.head ")) branch = line.slice(14).trim() || "(detached)";
      else if (line.startsWith("# branch.upstream ")) hasUpstream = true;
      else if (line.startsWith("# branch.ab ")) {
        const m = /\+(\d+)\s+-(\d+)/.exec(line);
        if (m) {
          ahead = Number(m[1]);
          behind = Number(m[2]);
        }
      }
    } else {
      dirty += 1;
    }
  }
  return { oid, branch, hasUpstream, ahead, behind, dirty };
}

function summarizeChecks(rollup) {
  let fail = 0;
  let pending = 0;
  let pass = 0;
  for (const item of rollup ?? []) {
    if (!item || typeof item !== "object") continue;
    if (item.__typename === "StatusContext" || (!item.status && item.state)) {
      const s = item.state;
      if (s === "FAILURE" || s === "ERROR") fail += 1;
      else if (s === "PENDING" || s === "EXPECTED") pending += 1;
      else if (s === "SUCCESS") pass += 1;
    } else {
      const st = item.status;
      const c = item.conclusion;
      if (st && st !== "COMPLETED") pending += 1;
      else if (FAIL_CONCLUSIONS.has(c)) fail += 1;
      else if (c === "SUCCESS" || c === "NEUTRAL" || c === "SKIPPED") pass += 1;
    }
  }
  const ci = fail > 0 ? "failing" : pending > 0 ? "pending" : pass > 0 ? "passing" : "none";
  return { ci, fail, pending, pass };
}

function parsePr(raw) {
  if (!raw || typeof raw !== "object" || !raw.url) return null;
  const checks = summarizeChecks(raw.statusCheckRollup);
  return {
    number: raw.number,
    url: raw.url,
    state: raw.state,
    isDraft: Boolean(raw.isDraft),
    reviewDecision: raw.reviewDecision || "",
    conflict: raw.mergeable === "CONFLICTING" || raw.mergeStateStatus === "DIRTY",
    ...checks,
  };
}

function localParts(g) {
  const parts = [];
  if (g.dirty > 0) parts.push(`${g.dirty} dirty`);
  if (g.ahead > 0) parts.push(`↑${g.ahead}`);
  if (g.behind > 0) parts.push(`↓${g.behind}`);
  return parts;
}

function badgeSpec(t, g, pr) {
  if (!g) return null;
  const local = localParts(g);
  const localDirty = g.dirty > 0 || g.ahead > 0;
  if (pr) {
    let iconPath = "mods/flat-agents/pr-open.svg";
    let color = t.accent;
    let stateLabel = "Open";
    if (pr.state === "MERGED") {
      iconPath = "mods/flat-agents/pr-merged.svg";
      color = t.ansi5;
      stateLabel = "Merged";
    } else if (pr.state === "CLOSED") {
      iconPath = "mods/flat-agents/pr-closed.svg";
      color = t.dim;
      stateLabel = "Closed";
    } else {
      if (pr.isDraft) {
        iconPath = "mods/flat-agents/pr-draft.svg";
        stateLabel = "Draft";
      }
      if (pr.conflict || pr.ci === "failing" || pr.reviewDecision === "CHANGES_REQUESTED") color = t.ansi1;
      else if (pr.ci === "pending") color = t.ansi3;
      else if (pr.isDraft) color = t.dim;
      else if (pr.reviewDecision === "APPROVED") color = t.ansi2;
      else color = t.accent;
    }
    const parts = [`PR #${pr.number} (${stateLabel})`, g.branch];
    if (pr.conflict) parts.push("Merge conflict");
    if (pr.ci === "failing") parts.push(`CI failing (${pr.fail})`);
    else if (pr.ci === "pending") parts.push(`CI running (${pr.pending})`);
    else if (pr.ci === "passing") parts.push("CI passing");
    if (pr.state === "OPEN") {
      if (pr.reviewDecision === "APPROVED") parts.push("Approved");
      else if (pr.reviewDecision === "CHANGES_REQUESTED") parts.push("Changes requested");
      else if (pr.reviewDecision === "REVIEW_REQUIRED") parts.push("Review required");
    }
    parts.push(...local);
    parts.push("Click to open");
    return { icon: iconPath, color, tooltip: parts.join(" · "), url: pr.url, localDirty };
  }
  if (isDefaultBranch(g) && g.dirty === 0 && g.ahead === 0 && g.behind === 0) return null;
  const color = localDirty ? t.ansi3 : g.behind > 0 ? t.muted : t.dim;
  const branchLabel = g.linked ? `${g.branch} (worktree)` : g.branch;
  const parts = [branchLabel, ...local];
  if (!isDefaultBranch(g)) parts.push(g.hasUpstream ? "No PR" : "Unpushed · No PR");
  return { icon: "mods/workspace-chrome/git-branch.svg", color, tooltip: parts.join(" · "), url: null, localDirty: false };
}

export default class Agents extends View {
  init(_props, cx) {
    if (props()?.sortMenu) return;
    this.folded = new Set();
    this.scroll = ScrollHandle.new();
    this.navOrder = [];
    this.rootOf = new Map();
    this.hasKids = new Set();
    this.listed = new Map();
    this.activeAt = -1;
    this.git = {}; // placeKey -> GitInfo | null
    this.gitChecked = {}; // placeKey -> ms
    this.gitUnsure = new Set();
    this.gitPending = new Set();
    this.gitRefreshing = false;
    this.defaultBranch = {}; // repoKey -> branch | null
    this.pr = {}; // prKey -> PrInfo | null
    this.prChecked = {}; // prKey -> ms
    this.prPending = new Map(); // prKey -> { cwd, on }
    this.prRefreshing = false;
    this.ghShell = {}; // machineKey -> boolean (fallback to login/interactive shell for GH_TOKEN/GITHUB_TOKEN)
    this.watching = new Map(); // watchPath -> FolderWatch
    this.busy = {}; // addr -> boolean
    this.placeOf = {}; // addr -> placeKey
    // Each agent's last state and when it changed (ms), kept across restarts.
    try { this.changed = JSON.parse(localStorage.getItem("changed") ?? "{}"); } catch { this.changed = {}; }
    if (!this.changed || typeof this.changed !== "object" || Array.isArray(this.changed)) this.changed = {};
    try { this.pendingPins = JSON.parse(localStorage.getItem("pins") ?? "[]"); } catch { this.pendingPins = []; }
    if (!Array.isArray(this.pendingPins)) this.pendingPins = [];
    if (!this.pendingPins.length) localStorage.removeItem("pins");
    this.migratingPins = new Set();
    cx.timer.every(30000, (cx) => cx.notify());
    if (!checking()) {
      this.syncGitPr(cx);
      cx.timer.every(1000, (cx) => this.syncGitPr(cx));
    }
    cx.spawn(async (cx) => {
      for (;;) {
        const command = await nextCommand();
        if (command === "next") this.step(1);
        else if (command === "prev") this.step(-1);
        else if (command === "toggle-children") this.toggleChildren(cx);
        else if (command === "open-pr") this.openPr(cx);
      }
    });
  }

  // All live agent and sub-agent terminals that can appear in this list.
  trackedTerminals() {
    const list = agents();
    const all = terminals();
    const byAddr = new Map(all.map((t) => [t.address, t]));
    const out = new Map();
    const add = (addr, status) => {
      const term = byAddr.get(addr);
      if (!term || term.state !== "live") return;
      out.set(addr, { addr, cwd: term.cwd || null, status });
    };
    const walk = (addr) => {
      for (const k of all) {
        if (k.parent !== addr || k.state !== "live" || out.has(k.address)) continue;
        add(k.address, k.status);
        walk(k.address);
      }
    };
    for (const a of list) {
      add(a.address, a.status);
      walk(a.address);
    }
    return out;
  }

  syncGitPr(cx) {
    const now = Date.now();
    const tracked = this.trackedTerminals();
    const activePlaces = new Set();
    const gitDue = new Set();
    const prDue = new Map();
    const placeOf = {};
    const busy = {};

    for (const [addr, info] of tracked) {
      const pk = placeKeyOf(addr, info.cwd);
      const working = info.status === "working";
      busy[addr] = working;
      if (pk) {
        activePlaces.add(pk);
        placeOf[addr] = pk;
        if (!(pk in this.git) || (this.placeOf[addr] && this.placeOf[addr] !== pk)) gitDue.add(pk);
        if (this.busy[addr] && !working) {
          gitDue.add(pk);
          const g = this.git[pk];
          if (g?.prKey && now - (this.prChecked[g.prKey] ?? 0) >= PR_TURN_COOLDOWN_MS) {
            prDue.set(g.prKey, { cwd: g.top, on: machineOf(addr) });
          }
        }
      }
    }
    this.placeOf = placeOf;
    this.busy = busy;

    // Drop stale git cache entries for closed terminals/worktrees.
    for (const pk of Object.keys(this.git)) {
      if (!activePlaces.has(pk)) {
        delete this.git[pk];
        delete this.gitChecked[pk];
        this.gitUnsure.delete(pk);
      }
    }

    // Drop stale PR cache entries and unused folder watches.
    const activePrKeys = new Map();
    const activeWatchPaths = new Set();
    for (const pk of activePlaces) {
      const g = this.git[pk];
      if (!g) continue;
      if (g.prKey) activePrKeys.set(g.prKey, { cwd: g.top, on: JSON.parse(pk)[0] });
      if (!JSON.parse(pk)[0]) {
        if (g.common) activeWatchPaths.add(g.common);
        if (g.gitDir && g.gitDir !== g.common) activeWatchPaths.add(g.gitDir);
      }
    }
    for (const prKey of Object.keys(this.pr)) {
      if (!activePrKeys.has(prKey)) {
        delete this.pr[prKey];
        delete this.prChecked[prKey];
      }
    }
    for (const [path, pending] of this.watching) {
      if (!activeWatchPaths.has(path)) {
        this.watching.delete(path);
        pending.cancel();
      }
    }

    const winActive = window()?.active ?? true;
    if (winActive) {
      for (const pk of activePlaces) {
        const asks = this.git[pk] || this.gitUnsure.has(pk);
        if (asks && now - (this.gitChecked[pk] ?? 0) > GIT_FALLBACK_MS) gitDue.add(pk);
      }
    }

    for (const [prKey, target] of activePrKeys) {
      const last = this.prChecked[prKey] ?? 0;
      const cur = this.pr[prKey];
      const pollMs = cur?.ci === "pending" ? PR_PENDING_POLL_MS : PR_POLL_MS;
      if (!(prKey in this.pr) || (winActive && now - last > pollMs)) {
        prDue.set(prKey, target);
      }
    }

    if (gitDue.size) this.refreshGit(gitDue, cx);
    if (prDue.size) this.refreshPr(prDue, cx);
  }

  refreshGit(keys, cx) {
    for (const k of keys) this.gitPending.add(k);
    if (this.gitRefreshing) return;
    this.gitRefreshing = true;
    cx.spawn(async (cx) => {
      while (this.gitPending.size) {
        const batch = [...this.gitPending];
        this.gitPending.clear();
        let next = 0;
        await Promise.all(Array.from({ length: Math.min(GIT_AT_ONCE, batch.length) }, async () => {
          while (next < batch.length) await this.checkGit(batch[next++], cx);
        }));
      }
      this.gitRefreshing = false;
      cx.notify();
    });
  }

  async checkGit(pk, cx) {
    const [on, cwd] = JSON.parse(pk);
    this.gitChecked[pk] = Date.now();
    this.gitUnsure.delete(pk);
    const prev = this.git[pk];
    try {
      const rev = await exec(
        "git",
        ["--no-optional-locks", "rev-parse", "--path-format=absolute", "--show-toplevel", "--git-common-dir", "--git-dir"],
        { cwd, on, timeout: 10000 },
      );
      if (rev.code !== 0) {
        if (/not a git repository/i.test(rev.stderr)) this.git[pk] = null;
        else {
          this.gitUnsure.add(pk);
          this.git[pk] ??= null;
        }
        return;
      }
      const lines = rev.stdout.trim().split("\n");
      if (lines.length < 3) {
        this.gitUnsure.add(pk);
        return;
      }
      const [top, common, gitDir] = lines;
      const repoKey = JSON.stringify([on, common]);
      const statusPromise = exec("git", ["--no-optional-locks", "status", "--porcelain=v2", "--branch"], { cwd: top, on, timeout: 10000 });
      const defPromise = repoKey in this.defaultBranch
        ? Promise.resolve(null)
        : exec("git", ["--no-optional-locks", "symbolic-ref", "-q", "refs/remotes/origin/HEAD"], { cwd: top, on, timeout: 5000 }).catch(() => null);
      const [stRes, defRes] = await Promise.all([statusPromise, defPromise]);
      if (defRes) {
        const ref = defRes.code === 0 ? defRes.stdout.trim() : "";
        const m = /^refs\/remotes\/[^/]+\/(.+)$/.exec(ref);
        this.defaultBranch[repoKey] = m ? m[1] : null;
      }
      if (stRes.code !== 0) {
        this.gitUnsure.add(pk);
        this.git[pk] ??= null;
        return;
      }
      const st = parseStatusV2(stRes.stdout);
      const defaultBranch = this.defaultBranch[repoKey] ?? null;
      const info = {
        top,
        common,
        gitDir,
        linked: gitDir !== common,
        ...st,
        defaultBranch,
        repoKey,
        dirKey: JSON.stringify([on, gitDir]),
        prKey: null,
      };
      if (!isDefaultBranch(info)) info.prKey = JSON.stringify([on, common, info.branch]);
      this.git[pk] = info;
      if (!on) {
        this.watchGitPath(common, "repo", repoKey, cx);
        if (gitDir !== common) this.watchGitPath(gitDir, "dir", info.dirKey, cx);
      }
      if (info.prKey) {
        const headChanged = !prev || prev.prKey !== info.prKey || prev.oid !== info.oid || prev.ahead !== info.ahead || prev.hasUpstream !== info.hasUpstream;
        if (headChanged || !(info.prKey in this.pr)) {
          this.refreshPr(new Map([[info.prKey, { cwd: info.top, on }]]), cx);
        }
      }
    } catch {
      this.git[pk] ??= null;
      this.gitUnsure.add(pk);
    }
  }

  watchGitPath(watchPath, kind, matchKey, cx) {
    if (this.watching.has(watchPath)) return;
    const pending = watchFolder(watchPath);
    this.watching.set(watchPath, pending);
    cx.spawn(async (cx) => {
      let current = pending;
      try {
        for (;;) {
          await current;
          if (this.watching.get(watchPath) !== current) return;
          const keys = Object.keys(this.git).filter((pk) => {
            const g = this.git[pk];
            if (!g) return false;
            return kind === "repo" ? g.repoKey === matchKey : g.dirKey === matchKey;
          });
          if (!keys.length) break;
          this.refreshGit(keys, cx);
          current = watchFolder(watchPath);
          this.watching.set(watchPath, current);
        }
      } catch {}
      if (this.watching.get(watchPath) === current) this.watching.delete(watchPath);
    });
  }

  refreshPr(targets, cx) {
    for (const [prKey, target] of targets) this.prPending.set(prKey, target);
    if (this.prRefreshing) return;
    this.prRefreshing = true;
    cx.spawn(async (cx) => {
      while (this.prPending.size) {
        const batch = [...this.prPending.entries()];
        this.prPending.clear();
        let next = 0;
        await Promise.all(Array.from({ length: Math.min(PR_AT_ONCE, batch.length) }, async () => {
          while (next < batch.length) {
            const [prKey, target] = batch[next++];
            await this.checkPr(prKey, target);
          }
        }));
      }
      this.prRefreshing = false;
      cx.notify();
    });
  }

  async runGh(args, { cwd, on }) {
    const mk = on ?? "";
    const runViaShell = () => exec(
      "sh",
      [
        "-c",
        'case "${SHELL:-}" in */zsh|*/bash) exec "$SHELL" -lic \'exec gh "$@"\' gh "$@" ;; *) PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH" exec gh "$@" ;; esac',
        "sh",
        ...args,
      ],
      { cwd, on, timeout: 15000 },
    );
    if (this.ghShell[mk]) return runViaShell();
    // macOS GUI apps often lack /opt/homebrew/bin and shell-exported GITHUB_TOKEN/GH_TOKEN.
    const r = await exec(
      "sh",
      ["-c", 'PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH" exec gh "$@"', "gh", ...args],
      { cwd, on, timeout: 12000 },
    );
    if (r.code === 4 || r.code === 127) {
      this.ghShell[mk] = true;
      return runViaShell();
    }
    return r;
  }

  async checkPr(prKey, { cwd, on }) {
    this.prChecked[prKey] = Date.now();
    try {
      const r = await this.runGh(["pr", "view", "--json", PR_FIELDS], { cwd, on });
      if (r.code === 0) {
        this.pr[prKey] = parsePr(JSON.parse(r.stdout));
        return;
      }
      if (/no pull requests found/i.test(r.stderr || r.stdout)) {
        this.pr[prKey] = null;
      }
    } catch {
      // Transient failure (offline, timeout): keep any previous PR data until next poll.
    }
  }

  openPr(cx) {
    const cur = focused()?.terminal ?? null;
    if (!cur) return;
    const term = terminals().find((t) => t.address === cur);
    const pk = placeKeyOf(cur, term?.cwd);
    const g = pk ? this.git[pk] : null;
    const pr = g?.prKey ? this.pr[g.prKey] : null;
    if (pr?.url) {
      cx.open_url(pr.url);
      return;
    }
    if (!pk) {
      notify({ title: "No PR found", body: "Focused agent has no working directory", level: "info", timeout: 3000 });
      return;
    }
    cx.spawn(async (cx) => {
      if (!this.git[pk]) await this.checkGit(pk, cx);
      const freshGit = this.git[pk];
      if (!freshGit) {
        notify({ title: "No PR found", body: "Focused agent is not in a git repository", level: "info", timeout: 3000 });
        return;
      }
      if (!freshGit.prKey) {
        notify({ title: "No PR found", body: `On branch ${freshGit.branch}`, level: "info", timeout: 3000 });
        return;
      }
      await this.checkPr(freshGit.prKey, { cwd: freshGit.top, on: machineOf(cur) });
      cx.notify();
      const freshPr = this.pr[freshGit.prKey];
      if (freshPr?.url) cx.open_url(freshPr.url);
      else notify({ title: "No PR found", body: `No pull request for branch ${freshGit.branch}`, level: "info", timeout: 3000 });
    });
  }

  gitBadge(t, addr, cwd) {
    const pk = placeKeyOf(addr, cwd);
    const g = pk ? this.git[pk] : null;
    const pr = g?.prKey ? this.pr[g.prKey] : null;
    const spec = badgeSpec(t, g, pr);
    if (!spec) return null;
    const el = div()
      .id(`git-${addr}`)
      .relative()
      .flex_none()
      .size(18)
      .flex()
      .items_center()
      .justify_center()
      .rounded(R)
      .text_color(spec.color)
      .tooltip(spec.tooltip)
      .child(svg(spec.icon).size(13).flex_none())
      .when(spec.localDirty, (b) => b.child(
        div()
          .absolute()
          .right(1)
          .bottom(1)
          .size(5)
          .rounded_full()
          .border(LINE)
          .border_color(t.chrome)
          .bg(t.ansi3),
      ));
    if (!spec.url) return el;
    return el
      .cursor_pointer()
      .hover((s) => s.bg(t.hover))
      .on_click((_e, cx) => {
        cx.stop_propagation();
        cx.open_url(spec.url);
      });
  }

  focusAddress(addr) {
    const cur = focused();
    // Stepping off a peeked unkept sub-agent onto a normal pane dismisses the peek.
    if (cur?.terminal && !cur.pane && !this.listed.has(cur.terminal) && this.listed.has(addr)) {
      run("overlay.close", {});
    }
    if (this.listed.has(addr)) run("pane.focus", { terminal: addr });
    else this.peek(addr);
  }

  step(dir) {
    const order = this.navOrder;
    if (!order.length) return;
    const cur = focused()?.terminal ?? null;
    let idx = cur ? order.indexOf(cur) : -1;
    // Focused on a child whose parent is folded: step relative to its parent.
    if (idx < 0 && cur && this.rootOf.has(cur)) idx = order.indexOf(this.rootOf.get(cur));
    const next = idx < 0
      ? (dir > 0 ? 0 : order.length - 1)
      : (idx + dir + order.length) % order.length;
    this.focusAddress(order[next]);
  }

  toggleChildren(cx) {
    const cur = focused()?.terminal ?? null;
    if (!cur) return;
    if (this.hasKids.has(cur)) {
      if (this.folded.has(cur)) this.folded.delete(cur);
      else this.folded.add(cur);
      cx.notify();
      return;
    }
    const root = this.rootOf.get(cur);
    if (!root) return;
    this.folded.add(root);
    this.focusAddress(root);
    cx.notify();
  }

  // Stamps agents whose state changed. Done and idle count as one: looking at a
  // finished agent turns done into idle, and looking isn't the agent doing anything.
  track(list, now) {
    let dirty = false;
    for (const a of list) {
      const s = a.status === "done" ? "idle" : a.status;
      if (this.changed[a.address]?.s === s) continue;
      this.changed[a.address] = { s, at: now };
      dirty = true;
    }
    if (!dirty) return;
    // Gone and old: the list alone is empty right after a start.
    const listed = new Set(list.map((a) => a.address));
    for (const [k, c] of Object.entries(this.changed)) if (!listed.has(k) && now - c.at > 30 * 86400000) delete this.changed[k];
    localStorage.setItem("changed", JSON.stringify(this.changed));
  }

  // Keep offline pins until their terminal returns, and keep each pending until
  // core echoes the label so a failed write doesn't erase the old pin.
  migratePins(all) {
    const listed = new Map(all.filter((t) => t.state === "live").map((t) => [t.address, t]));
    const pending = this.pendingPins.filter((address) => {
      const terminal = listed.get(address);
      if (!terminal) return true;
      if (terminal.labels?.["herdr.pinned"]) return false;
      if (!this.migratingPins.has(address)) {
        this.migratingPins.add(address);
        run("terminal.pin", { terminal: address, pinned: true });
      }
      return true;
    });
    if (pending.length === this.pendingPins.length) return;
    this.pendingPins = pending;
    if (pending.length) localStorage.setItem("pins", JSON.stringify(pending));
    else localStorage.removeItem("pins");
  }

  since(a) {
    return this.changed[a.address]?.at ?? 0;
  }

  rank(a) {
    return RANK[a.status] ?? 0;
  }

  sortMenu(t) {
    const on = sortOf().id;
    return v_flex()
      .w_full()
      .p(S1)
      .bg(t.popover).border(LINE).border_color(t.border).rounded(R)
      .text_size(TEXT)
      .child(div().px(S2).pt(S1).pb(S1).text_size(SMALL).text_color(t.dim).child("Sort agents"))
      .children(SORTS.map((s) => h_flex()
        .id(`sort-${s.id}`)
        .h(31)
        .px(S2)
        .gap(S2)
        .rounded(R)
        .items_center()
        .text_color(t.foreground)
        .hover((el) => el.bg(t.hover))
        .on_click(() => {
          setShared("agents.sort", s.id);
          closeOverlay(props().overlay);
        })
        .child(svg(`mods/workspace-chrome/${s.icon}.svg`).size(14).flex_none().text_color(t.muted))
        .child(div().flex_1().child(s.label))
        .when(s.id === on, (el) => el.child(svg("mods/workspace-chrome/check.svg").size(14).flex_none().text_color(t.foreground)))));
  }

  peek(addr) {
    run("terminal.peek", { terminal: addr });
  }

  // Live sub-agents of `addr`, depth first, each with the tree lines in front of it.
  tree(all, addr, lead = []) {
    const kids = all.filter((k) => k.parent === addr && k.state === "live");
    return kids.flatMap((k, i) => {
      const last = i === kids.length - 1;
      return [
        { t: k, lines: [...lead, last ? "└" : "├"] },
        ...this.tree(all, k.address, [...lead, last ? "" : "│"]),
      ];
    });
  }

  subRow(t, s, activeAddr, compact) {
    const k = s.t;
    const st = kidStatus(k, this.listed);
    const pic = icon(k.program, 14, t.foreground);
    const on = k.address === activeAddr;
    const badge = this.gitBadge(t, k.address, k.cwd);
    return h_flex()
      .id(`sub-${k.address}`)
      .pl(S2 + 22 + S2) // under the parent row's name: its padding + icon + gap
      .pr(S2)
      .rounded(R)
      .h(26)
      .flex_none()
      .gap(0)
      .items_center()
      .text_size(TEXT)
      .when(on, (el) => el.bg(t.selected))
      .hover((s) => s.bg(t.hover))
      .on_click(() => (this.listed.has(k.address) ? run("pane.focus", { terminal: k.address }) : this.peek(k.address)))
      .children(s.lines.map(l => div().self_start().mt(-4).w(9).h(17).mr(4).flex_none()
        .when(Boolean(l), el => el.border_l(LINE).border_color(t.input))
        .when(l === "└" || l === "├", el => el.border_b(LINE).rounded_bl(R))))
      .when(Boolean(pic), el => el.child(div().mr(8).child(pic)))
      .child(div().flex_1().truncate().text_color(on ? t.foreground : t.muted).child(k.name || k.template || k.program?.name || k.address))
      .when(Boolean(badge), el => el.child(div().mr(4).child(badge)))
      .child(this.status(t, { status: st }, compact));
  }

  // compact: a ! for blocked where a header already says "Needs you".
  status(t, a, compact = false) {
    const color = t[a.status] ?? t.dim;
    if (a.status === "working") return svg("mods/workspace-chrome/spinner.svg").size(12).mx(1).flex_none().text_color(t.working).spin(900);
    if (a.status === "blocked" && compact) return div().size(14).flex_none().rounded(R).bg(t.blocked + "26").text_size(SMALL).font_bold().text_color(t.blocked).flex().items_center().justify_center().child("!");
    if (a.status === "blocked") return div().flex_none().px(S1).h(18).rounded(R).bg(t.blocked + "26").text_size(SMALL).font_semibold().text_color(t.blocked).flex().items_center().child("Needs you");
    // Idle: a ring; done: a dot.
    if (a.status === "idle") return div().size(7).mx(3).flex_none().rounded_full().border(LINE).border_color(t.idle ?? t.dim);
    return div().size(7).mx(3).flex_none().rounded_full().bg(a.status === "done" ? color : t.dim + "00");
  }

  render(cx) {
    const t = theme();
    if (props()?.sortMenu) return this.sortMenu(t);
    const collapsed = narrow();
    const sort = sortOf();
    let list = agents();
    this.listed = new Map(list.map((a) => [a.address, a.status]));
    const all = terminals();
    this.migratePins(all);
    const activeAddr = focused()?.terminal ?? null;
    const now = Date.now();
    this.track(list, now);
    // A kept sub-agent (one with a pane) is in agents() too: where a tree shows
    // it, it gets no row of its own, unless it's pinned.
    const nested = new Set(collapsed ? [] : list.flatMap((a) => this.tree(all, a.address).map((s) => s.t.address)));
    list = list.filter((a) => a.pinned || !nested.has(a.address));
    const tabCounts = new Map();
    for (const a of list) tabCounts.set(a.tab, (tabCounts.get(a.tab) ?? 0) + 1);
    const byPriority = sort.id === "priority";
    // A helper's done is its own row's news: it doesn't pull a working parent out of Working.
    const kidRank = (k) => { const s = kidStatus(k, this.listed); return RANK[s === "done" ? "idle" : s] ?? 0; };
    const urgency = new Map(list.map((a) => [a.address, Math.max(this.rank(a), ...this.tree(all, a.address).map((s) => kidRank(s.t)))]));
    const rankOf = (a) => urgency.get(a.address);
    if (byPriority) list = [...list].sort((x, y) => rankOf(y) - rankOf(x) || this.since(y) - this.since(x) || y.seq - x.seq);
    const pinned = list.filter((a) => a.pinned);
    const rest = list.filter((a) => !a.pinned);
    list = [...pinned, ...rest];

    // The fold chevron; folded, the count too, colored by the most urgent one.
    const fold = (a, subs) => {
      const sts = subs.map((s) => kidStatus(s.t, this.listed));
      const top = sts.reduce((m, s) => ((RANK[s] ?? 0) > (RANK[m] ?? 0) ? s : m), null);
      const open = !this.folded.has(a.address);
      return div()
        .id(`fold-${a.address}`)
        .h(18)
        .px(S1)
        .gap(S1)
        .flex()
        .items_center()
        .rounded(R)
        .text_size(SMALL)
        .text_color(open ? t.dim : (t[top] ?? t.dim))
        .cursor_pointer()
        .hover((s) => s.bg(t.hover).text_color(t.foreground))
        .on_click((_e, cx) => {
          cx.stop_propagation();
          open ? this.folded.add(a.address) : this.folded.delete(a.address);
          cx.notify();
        })
        .child(svg(`mods/workspace-chrome/chevron-${open ? "down" : "right"}.svg`).size(11).flex_none())
        .when(!open, (el) => el.child(String(subs.length)));
    };

    // A row reads space, then detail on its second line: the detail is a tab someone named or the
    // agent's own title, never an automatic tab number unless two rows would
    // otherwise read the same.
    // Read the pane snapshot once: every host read copies the whole list into JS.
    const leads = leadPanes(panes());
    const tabs = new Map(spaces().flatMap(s => s.tabs).map(tab => [tab.id, tab]));
    const byAddress = new Map(terminals().map((x) => [x.address, x]));
    const labels = new Map(list.map(a => {
      const tab = tabs.get(a.tab);
      const many = tabCounts.get(a.tab) > 1;
      const l = many ? a : leads.get(a.tab);
      return [a.address, tab ? title(many ? { ...tab, named: false } : tab, l, sessionTitle(byAddress, l))
        : (sessionTitle(byAddress, a) || clean(a.title) || a.program?.name || "")];
    }));
    const label = (a) => labels.get(a.address);
    const detail = new Map(list.map(a => [a.address, /^\d+$/.test(label(a)) ? null : label(a)]));
    const seen = {};
    for (const a of list) { const k = `${a.space_name}\u0000${detail.get(a.address) ?? ""}`; seen[k] = (seen[k] ?? 0) + 1; }
    for (const a of list) {
      if (detail.get(a.address) == null && seen[`${a.space_name}\u0000`] > 1) detail.set(a.address, label(a));
    }

    const row = (a, i, subs = []) => {
      const pic = icon(a.program, 16, t.foreground);
      const more = detail.get(a.address);
      // An agent on another machine (`vps/t7`) says which.
      const machine = a.address.includes("/") ? a.address.split("/")[0] : null;
      if (collapsed) {
        return h_flex()
          .id(`ag-${a.address}`)
          .h(26)
          .mx(S1)
          .px(HAIR)
          .rounded(R)
          .flex_none()
          .items_center()
          .gap(S1)
          .when(a.focused && (!activeAddr || activeAddr === a.address), (el) => el.bg(t.selected))
          .hover((s) => s.bg(t.hover))
          .on_click(() => run("pane.focus", { pane: a.pane }))
          .child(div().flex_1().min_w(0).whitespace_nowrap().text_right().text_color(a.focused ? t.foreground : t.muted).child(String(i + 1)))
          .child(h_flex().w(14).flex_none().items_center().justify_center().child(this.status(t, a, true)));
      }
      const when = this.since(a);
      const idle = a.status === "idle" && !a.focused;
      const isPinned = a.pinned;
      const pin = div()
        .id(`pin-${a.address}`)
        .flex_none()
        .p(HAIR)
        .rounded(R)
        .text_color(t.dim)
        .cursor_pointer()
        .hover((s) => s.bg(t.hover).text_color(t.foreground))
        .tooltip(isPinned ? "Unpin" : "Pin to the top")
        .on_click((_e, cx) => {
          cx.stop_propagation();
          run("terminal.pin", { terminal: a.address, pinned: !isPinned });
          // The row moves away from under the pointer, and no hover-out comes.
          this.hovered = null;
          cx.notify();
        })
        .child(svg(`mods/workspace-chrome/${isPinned ? "pin-off" : "pin"}.svg`).size(13));
      // Under a space header the space goes without saying; an automatic tab number says nothing.
      // Without a space header above (priority, pinned) the row names its space.
      // There the row takes two lines: the space and the rest, then the title.
      const full = byPriority || isPinned;
      const name = full ? a.space_name || label(a) : more ?? (/^\d+$/.test(label(a)) ? a.program?.name || label(a) : label(a));
      const badge = this.gitBadge(t, a.address, byAddress.get(a.address)?.cwd);
      const line = h_flex()
        .h(full ? 20 : 30)
        .items_center()
        .gap(S2)
        .when(Boolean(pic), el => el.child(div().id(`agent-fold-${a.address}`)
          .when(subs.length > 0, el => el.on_click((_e, cx) => {
            cx.stop_propagation();
            this.folded.has(a.address) ? this.folded.delete(a.address) : this.folded.add(a.address);
            cx.notify();
          })).child(pic)))
        .child(div().flex_1().min_w(0).truncate().text_color(full ? t.dim : idle ? t.muted : t.foreground).child(name))
        .when(Boolean(machine), el => el.child(div().text_size(SMALL).text_color(t.dim).child(machine)))
        .when(subs.length > 0, el => el.child(fold(a, subs)))
        .when(this.hovered === a.address, el => el.child(pin))
        .when(this.hovered !== a.address && Boolean(when), el => el.child(div().flex_none().text_size(SMALL).text_color(t.dim).child(duration(now - when))))
        .when(Boolean(badge), el => el.child(badge))
        .child(this.status(t, a, byPriority && !isPinned));
      return v_flex()
        .id(`ag-${a.address}`)
        .px(S2)
        .when(full, el => el.py(S1))
        .flex_none()
        .rounded(R)
        .justify_center()
        .when(a.focused && (!activeAddr || activeAddr === a.address), (el) => el.bg(t.selected))
        .cursor_pointer()
        .hover((s) => s.bg(t.hover))
        .on_hover((on, cx) => {
          if (on) this.hovered = a.address;
          else if (this.hovered === a.address) this.hovered = null;
          cx.notify();
        })
        .on_click(() => run("pane.focus", { pane: a.pane }))
        .child(line)
        .when(full, el => el.child(div().h(20).flex().items_center()
          .child(div().min_w(0).truncate().text_color(idle ? t.muted : t.foreground).child(more ?? a.program?.name ?? ""))));
    };

    // Groups in list order: spaces (grouped) or priority sections. Agents of a
    // space are next to each other in agents(), so neighbours make a group.
    const groups = pinned.length ? [{ id: "pinned", label: "Pinned", status: null, members: pinned }] : [];
    for (const a of rest) {
      const r = rankOf(a) || RANK.idle;
      const id = byPriority ? `sec-${r}` : `sp-${a.space}`;
      if (groups.at(-1)?.id === id) groups.at(-1).members.push(a);
      else groups.push({ id, label: byPriority ? SECTION[r] : a.space_name || "", status: byPriority ? SECTION_STATUS[r] : null, members: [a] });
    }

    // A group's header; it folds the group. Folded, it says how many and the most urgent state.
    const header = (g) => {
      const open = !this.folded.has(g.id);
      const top = g.members.reduce((m, a) => ((RANK[a.status] ?? 0) > (RANK[m] ?? 0) ? a.status : m), null);
      return h_flex()
        .id(g.id)
        .px(S2)
        .pt(S2)
        .h(30)
        .flex_none()
        .gap(S1)
        .items_center()
        .text_size(SMALL)
        .font_medium()
        .cursor_pointer()
        .hover((s) => s.text_color(t.foreground))
        .on_click((_e, cx) => {
          open ? this.folded.add(g.id) : this.folded.delete(g.id);
          cx.notify();
        })
        .child(div().truncate().text_color(t[g.status] ?? t.dim).child(g.label))
        .when(byPriority || !open, (el) => el.child(div().text_color(t.dim).child(String(g.members.length))))
        .child(div().flex_1())
        .when(!open, (el) => el
          .when(!byPriority && top && top !== "idle", (el) => el.child(this.status(t, { status: top }, true)))
          .child(svg("mods/workspace-chrome/chevron-right.svg").size(11).flex_none().text_color(t.dim)));
    };
    const navOrder = [];
    const seenNav = new Set();
    const addNav = (addr) => {
      if (seenNav.has(addr)) return;
      seenNav.add(addr);
      navOrder.push(addr);
    };
    const rootOf = new Map();
    const hasKids = new Set();
    let activeAt = -1;
    const rows = [];
    const pushParent = (a, i) => {
      const subs = collapsed ? [] : this.tree(all, a.address);
      if (subs.length > 0) hasKids.add(a.address);
      for (const s of subs) rootOf.set(s.t.address, a.address);
      if (activeAddr === a.address && activeAt < 0) activeAt = rows.length;
      rows.push(row(a, i, subs));
      addNav(a.address);
      if (!this.folded.has(a.address)) {
        for (const s of subs) {
          if (activeAddr === s.t.address && activeAt < 0) activeAt = rows.length;
          rows.push(this.subRow(t, s, activeAddr, byPriority));
          addNav(s.t.address);
        }
      }
    };
    if (collapsed) {
      list.forEach((a, i) => pushParent(a, i));
    } else {
      let idx = 0;
      for (const g of groups) {
        rows.push(header(g));
        const foldedGroup = this.folded.has(g.id);
        for (const a of g.members) {
          const i = idx++;
          if (foldedGroup) {
            const subs = this.tree(all, a.address);
            if (subs.length > 0) hasKids.add(a.address);
            for (const s of subs) rootOf.set(s.t.address, a.address);
            continue;
          }
          pushParent(a, i);
        }
      }
    }
    this.navOrder = navOrder;
    this.rootOf = rootOf;
    this.hasKids = hasKids;
    this.activeAt = activeAt;
    setAgentOrder(navOrder);
    if (activeAddr !== this.revealed || activeAt !== this.revealedAt) {
      this.revealed = activeAddr;
      this.revealedAt = activeAt;
      if (activeAt >= 0) this.scroll.scroll_to_item(activeAt);
    }

    return v_flex()
      .size_full()
      .min_h(0)
      .bg(t.chrome)
      .border_t(LINE)
      .border_color(t.border)
      .text_size(TEXT)
      .when(!collapsed, (el) =>
        el.child(
          h_flex()
            .px(S3)
            .h(41)
            .pt(S3)
            .pb(S1)
            .flex_none()
            .items_center()
            .justify_between()
            .child(div().text_size(SMALL).font_medium().text_color(t.dim).child("Agents"))
            .child(
              div()
                .id("ag-sort")
                .text_size(SMALL)
                .text_color(t.dim)
                .hover((s) => s.text_color(t.foreground))
                .on_click(() => openOverlay({ mod: "flat-agents", kind: "popup", frame: "none", width: 200, height: 140, props: { sortMenu: true } }))
                .tooltip(`Sort agents: ${sort.label}`)
                .child(svg(`mods/workspace-chrome/${sort.icon}.svg`).size(14)),
            ),
        ),
      )
      .when(list.length === 0 && !collapsed, (el) =>
        el.child(div().px(S2).text_size(TEXT).text_color(t.dim).child("No agent status yet. Agents show up here when they report their status. Older versions and agents inside tmux may not.")),
      )
      .child(
        v_flex()
          .id("ag-list")
          .flex_1()
          .min_h(0)
          .px(collapsed ? 0 : S2)
          .overflow_y_scrollbar()
          .mode("always")
          .track_scroll(this.scroll)
          .on_size_change((_size, cx) => { if (this.activeAt >= 0) { this.scroll.scroll_to_item(this.activeAt); cx.notify(); } })
          .children(rows),
      )
      .when(collapsed, (el) =>
        el.child(
          h_flex()
            .h(28)
            .items_center()
            .justify_center()
            .child(
              div()
                .id("collapse")
                .text_size(TEXT)
                .text_color(t.dim)
                .hover((s) => s.text_color(t.foreground))
                .on_click(toggleSidebar)
                .child("»"),
            ),
        ),
      );
  }
}
